SELECT 'gongkao', '两人年龄差应用', 'kp-age-d-two-people', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "“当我像你这么大时”经典模型"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心绝招：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "画线段，等距切分。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "究极高频题：“哥哥对弟弟说：当我像你这么大时，你才 5 岁；等你长到我这么大时，我已经 20 岁了。”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "把这四个人生阶段画在一条年龄线段上：5岁 ---> 弟弟现龄 ---> 哥哥现龄 ---> 20岁。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "因为年龄差不变，所以这三段间距是【完全相等】的！"}]}, {"type": "katexBlock", "attrs": {"content": "3 \\times \\text{年龄差} = 20 - 5 = 15 \\quad \\Rightarrow \\quad \\text{年龄差} = 5"}}]}$$ AS jsonb), NULL, '两人年龄差应用的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "两人年龄差应用"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_d_two_people", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
